The minimal subarray with a repeated value is determined by the closest pair of equal elements. Scanning the array once while remembering the last index of each value gives the distance `i - last[value] + 1` for every new occurrence. Keeping the smallest distance found yields the answer, or `-1` when no value repeats.

```python
import sys

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1 + n]
    if len(a) < n:
        # in case of malformed input, pad
        a += [0] * (n - len(a))
    last = {}
    ans = n + 1
    for i, v in enumerate(a, 1):
        prev = last.get(v)
        if prev is not None:
            d = i - prev + 1
            if d < ans:
                ans = d
                if ans == 2:   # optimal possible
                    print(2)
                    return
        last[v] = i
    if ans == n + 1:
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
