def set_left_most_unset_bit(n: int) -> int:
    """
    Set the left-most (most significant) unset bit in the binary representation of n.
    If n is all 1s in its current bit length, the bit is extended by one.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1  # 0 -> 1

    bit_len = n.bit_length()
    # scan from most significant bit down to 0
    for i in range(bit_len - 1, -1, -1):
        if ((n >> i) & 1) == 0:
            return n | (1 << i)
    # all bits are 1, extend
    return n | (1 << bit_len)


