The robot can only move right or down, so the best value for each cell depends on the best values of the cell above and to the left. Keeping three layers of dynamic programming captures the effect of using zero, one or two neutralizations. For a non-negative cell the value is simply added, while for a negative cell we may either keep the penalty or discard it by spending one neutralization. Propagating the best of the two predecessors preserves optimality and the monotonicity between layers guarantees that using fewer neutralizations is never worse.

```python
from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m = len(coins)
        n = len(coins[0])
        NEG = -10**18

        # dp[k][i][j] = best profit with at most k neutralisations
        dp = [[[NEG] * n for _ in range(m)] for _ in range(3)]

        v0 = coins[0][0]
        if v0 >= 0:
            for k in range(3):
                dp[k][0][0] = v0
        else:
            dp[0][0][0] = v0
            dp[1][0][0] = 0
            dp[2][0][0] = 0

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = coins[i][j]
                for k in range(3):
                    best = NEG
                    if i > 0:
                        best = max(best, dp[k][i - 1][j])
                    if j > 0:
                        best = max(best, dp[k][i][j - 1])
                    if best == NEG:
                        continue
                    if val >= 0:
                        dp[k][i][j] = best + val
                    else:
                        # do not neutralise
                        cur = best + val
                        # neutralise current cell
                        if k > 0:
                            best_prev = NEG
                            if i > 0:
                                best_prev = max(best_prev, dp[k - 1][i - 1][j])
                            if j > 0:
                                best_prev = max(best_prev, dp[k - 1][i][j - 1])
                            if best_prev != NEG:
                                cur = max(cur, best_prev)   # +0
                        dp[k][i][j] = cur
                # monotonicity: more neutralisations cannot hurt
                if dp[1][i][j] < dp[0][i][j]:
                    dp[1][i][j] = dp[0][i][j]
                if dp[2][i][j] < dp[1][i][j]:
                    dp[2][i][j] = dp[1][i][j]

        return dp[2][m - 1][n - 1]
```

