def is_samepatterns(a, b):
    """
    Return True if a and b have the same equality pattern.
    i.e. for all i,j: a[i] == a[j]  <=>  b[i] == b[j]
    """
    if len(a) != len(b):
        return False

    map_ab = {}
    map_ba = {}

    for x, y in zip(a, b):
        # forward mapping a -> b
        if x in map_ab:
            if map_ab[x] != y:
                return False
        else:
            map_ab[x] = y

        # reverse mapping b -> a to enforce bijection
        if y in map_ba:
            if map_ba[y] != x:
                return False
        else:
            map_ba[y] = x

    return True


