Processing is done by sweeping events in chronological order while maintaining a min-heap of pending returns. Offline events push a return time 60 units later and set the user offline immediately. Before each event all returns whose time has arrived are applied, guaranteeing that status changes precede messages at the same timestamp. Message tokens are then expanded: `ALL` increments every user, `HERE` increments only online users, and `idk` increments the specific user. Sorting ensures OFFLINE events are handled before MESSAGE events sharing a timestamp.

```python
class Solution:
    def countMentions(self, numberOfUsers: int, events: list[list[str]]) -> list[int]:
        import heapq
        mentions = [0] * numberOfUsers
        online = [True] * numberOfUsers

        parsed = []
        for ev in events:
            typ = ev[0]
            ts = int(ev[1])
            if typ == "OFFLINE":
                uid = int(ev[2])
                parsed.append((ts, 0, "OFFLINE", uid))   # priority 0
            else:  # MESSAGE
                s = ev[2]
                parsed.append((ts, 1, "MESSAGE", s))      # priority 1

        parsed.sort(key=lambda x: (x[0], x[1]))

        heap = []  # (return_time, user_id)

        for ts, _, typ, data in parsed:
            # bring users back online before handling the event
            while heap and heap[0][0] <= ts:
                _, uid = heapq.heappop(heap)
                online[uid] = True

            if typ == "OFFLINE":
                uid = data
                online[uid] = False
                heapq.heappush(heap, (ts + 60, uid))
            else:  # MESSAGE
                tokens = data.split()
                for tok in tokens:
                    if tok == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif tok == "HERE":
                        for u in range(numberOfUsers):
                            if online[u]:
                                mentions[u] += 1
                    elif tok.startswith("id"):
                        try:
                            uid = int(tok[2:])
                        except ValueError:
                            continue
                        if 0 <= uid < numberOfUsers:
                            mentions[uid] += 1
                    # unknown token ignored
        return mentions
```

The Manhattan distance can be expressed through four sign choices, each turning the walk into a sum of `+1` and `-1` contributions. For a fixed prefix the number of `-1` contributions determines how much can be improved by flipping at most `k` steps, because a flipped step can always be made `+1`. The best achievable value for a sign pattern is `t - 2*max(0, neg - k)`, where `neg` is the count of bad steps. Scanning the string while maintaining the four direction counters yields the optimum over all prefixes in linear time.

```python
class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        cntN = cntS = cntE = cntW = 0
        ans = 0
        for ch in s:
            if ch == 'N':
                cntN += 1
            elif ch == 'S':
                cntS += 1
            elif ch == 'E':
                cntE += 1
            else:  # 'W'
                cntW += 1

            t = cntN + cntS + cntE + cntW
            # number of -1 positions for the four sign combos
            neg1 = cntW + cntS          # sx=+1, sy=+1
            neg2 = cntW + cntN          # sx=+1, sy=-1
            neg3 = cntE + cntS          # sx=-1, sy=+1
            neg4 = cntE + cntN          # sx=-1, sy=-1

            def score(neg):
                return t - 2 * max(0, neg - k)

            cur = max(score(neg1), score(neg2), score(neg3), score(neg4))
            if cur > ans:
                ans = cur
        return ans
```

