def is_simple_power(x, n):
    # 0**k = 0 for k>0, 0**0 is undefined
    if n == 0:
        return x == 0
    if x == 0:
        return False
    # any non-zero number to the power 0 is 1
    if x == 1:
        return True
    if n == 1:
        return False
    if n == -1:
        return x in (1, -1)
    if x < 0 and n > 0:
        return False

    power = 1
