def minPath(grid, k):
    n = len(grid)
    # find the cell containing 1
    start_i = start_j = None
    for i in range(n):
        row = grid[i]
        for j, v in enumerate(row):
            if v == 1:
                start_i, start_j = i, j
                break
        if start_i is not None:
            break

    best = {}

    def best_neighbor(i, j):
        key = (i, j)
        if key in best:
            return best[key]
        bval = None
        bi = bj = None
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                v = grid[ni][nj]
                if bval is None or v < bval:
                    bval = v
                    bi, bj = ni, nj
        best[key] = (bi, bj)
        return bi, bj

    visited = {}
    nodes = []
    cur_i, cur_j = start_i, start_j

    while True:
        if (cur_i, cur_j) in visited:
            start_cycle = visited[(cur_i, cur_j)]
            cycle_len = len(nodes) - start_cycle
            if k <= len(nodes):
                res_nodes = nodes[:k]
            else:
                prefix = nodes[:start_cycle]
                cycle_nodes = nodes[start_cycle:]
                need = k - start_cycle
                # build the remaining part using the cycle
                res_nodes = prefix + [cycle_nodes[i % cycle_len] for i in range(need)]
            return [grid[i][j] for i, j in res_nodes]

        if len(nodes) >= k:
            res_nodes = nodes[:k]
            return [grid[i][j] for i, j in res_nodes]

        visited[(cur_i, cur_j)] = len(nodes)
        nodes.append((cur_i, cur_j))
        cur_i, cur_j = best_neighbor(cur_i, cur_j)

